from collections import deque
from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump_to = dict(jumps)
    resolved = list(range(n + 1))
    for cell in range(n + 1):
        destination = cell
        while destination in jump_to:
            destination = jump_to[destination]
        resolved[cell] = destination

    states = [0]
    index = {0: 0}
    transitions = []
    reverse = [[] for _ in range(n + 1)]

    for position in states:
        counts = {}
        for roll in range(1, m + 1):
            landing = position + roll
            if landing > n:
                landing = 2 * n - landing
            destination = resolved[landing]
            counts[destination] = counts.get(destination, 0) + 1

        transitions.append(counts)
        for destination in counts:
            reverse[destination].append(position)
            if destination != n and destination not in index:
                index[destination] = len(states)
                states.append(destination)

    # Every reachable state must have a path to the terminal state.
    can_finish = [False] * (n + 1)
    can_finish[n] = True
    queue = deque([n])
    while queue:
        destination = queue.popleft()
        for position in reverse[destination]:
            if not can_finish[position]:
                can_finish[position] = True
                queue.append(position)

    if any(not can_finish[position] for position in states):
        return None

    # The expectation equations are:
    # m * E[position] - sum(count * E[destination]) = m.
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]
    for i, counts in enumerate(transitions):
        matrix[i][i] = m
        matrix[i][size] = m
        for destination, count in counts.items():
            if destination != n:
                matrix[i][index[destination]] -= count

    # Bareiss elimination keeps all intermediate entries integral.
    previous_pivot = 1
    for k in range(size - 1):
        if matrix[k][k] == 0:
            pivot_row = next(
                i for i in range(k + 1, size) if matrix[i][k] != 0
            )
            matrix[k], matrix[pivot_row] = matrix[pivot_row], matrix[k]

        pivot = matrix[k][k]
        pivot_row = matrix[k]
        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0
        previous_pivot = pivot

    expectations = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * expectations[j]
        expectations[i] = value / matrix[i][i]

    answer = expectations[0]
    return [answer.numerator, answer.denominator]
